import axiosInstance from '@/apis/authPromise';
const backendBaseURL = import.meta.env.VITE_JAVA_BACKEND_URL ?? "http://localhost:8080";
export const getAllAntiques = async () => {
    const response = await axiosInstance.get(`${backendBaseURL}/api/antiques`);
    const payload = response.data;
    if (Array.isArray(payload))
        return payload;
    return payload.content ?? payload.antiques ?? payload.data ?? [];
};
export const addAntique = async (antique) => {
    const response = await axiosInstance.post(`${backendBaseURL}/api/antiques`, antique);
    return response.data;
};
export const uploadAntiqueImage = async (id, image) => {
    const body = new FormData();
    body.append("image", image);
    await axiosInstance.put(`${backendBaseURL}/api/antiques/${id}/image`, body, { headers: { "Content-Type": "multipart/form-data" } });
};
export const getVisibleCategories = async () => {
    const response = await axiosInstance.get(`${backendBaseURL}/api/categories`);
    return response.data;
};
export const getAllCategories = async () => {
    const response = await axiosInstance.get(`${backendBaseURL}/api/categories/admin`);
    return response.data;
};
export const updateCategory = async (category) => {
    const response = await axiosInstance.put(`${backendBaseURL}/api/categories/${category.id}`, {
        name: category.name,
        parentId: category.parentId ?? null,
        visible: category.visible,
    });
    return response.data;
};
export const createCategory = async (name, parentId) => {
    const response = await axiosInstance.post(`${backendBaseURL}/api/categories`, { name, parentId: parentId || null, visible: true });
    return response.data;
};
export const deleteCategory = async (id) => {
    await axiosInstance.delete(`${backendBaseURL}/api/categories/${id}`);
};
export const getStoreLocation = async () => {
    const response = await axiosInstance.get(`${backendBaseURL}/api/location`);
    return response.data;
};
export const updateStoreLocation = async (location) => {
    const response = await axiosInstance.put(`${backendBaseURL}/api/location`, location);
    return response.data;
};
export const createCheckoutSession = async (items) => {
    const response = await axiosInstance.post(`${backendBaseURL}/api/checkout`, { items });
    return response.data.checkoutUrl;
};
